// Generated by pixelmark from brand/openreview-mark.svg. Re-run pixelmark to update; edit the rows by hand if you like.
/**
 * Terminal renderer for pixel-art logos. Each terminal cell holds two square
 * pixels drawn with half-block characters (▀ ▄ █).
 *
 * A swatch marked `adaptive` is drawn in the terminal's own foreground colour,
 * so a black or white logo reads on dark and light themes alike. Other
 * swatches keep their exact colour.
 *
 * This file has no dependencies; pixelmark copies it into generated modules.
 */

export type ColorLevel = "none" | "16" | "256" | "truecolor";

export interface Swatch {
  hex: string;
  adaptive: boolean;
}

export interface Art {
  name: string;
  palette: Swatch[];
  /** Pixel rows per size: "." is empty, "a" is palette[0], "b" palette[1]… */
  sizes: Record<string, string[]>;
}

export interface MarkOptions {
  color?: ColorLevel;
  size?: string;
  /** Fixed hex colour for adaptive swatches instead of the terminal foreground. */
  ink?: string;
}

export interface BannerInfo {
  version?: string;
  /** Lines under the name, such as a tagline, repository or model. */
  details?: string[];
}

const ESC = "\x1b[";
const RESET = `${ESC}0m`;

export function detectColorLevel(env: NodeJS.ProcessEnv = process.env): ColorLevel {
  if (env.NO_COLOR !== undefined && env.NO_COLOR !== "") return "none";
  if (env.FORCE_COLOR === "0") return "none";
  if (env.FORCE_COLOR === "3") return "truecolor";
  const colorterm = (env.COLORTERM ?? "").toLowerCase();
  if (colorterm === "truecolor" || colorterm === "24bit") return "truecolor";
  if (env.TERM_PROGRAM === "iTerm.app" || env.TERM_PROGRAM === "WezTerm" || env.TERM_PROGRAM === "ghostty" || env.WT_SESSION) return "truecolor";
  const term = (env.TERM ?? "").toLowerCase();
  if (term === "dumb") return "none";
  if (term.includes("256")) return "256";
  return "16";
}

function rgb(hex: string): [number, number, number] {
  const n = Number.parseInt(hex.replace("#", ""), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

const ANSI16: [number, number, number][] = [
  [0, 0, 0], [205, 0, 0], [0, 205, 0], [205, 205, 0], [0, 0, 238], [205, 0, 205], [0, 205, 205], [229, 229, 229],
  [127, 127, 127], [255, 0, 0], [0, 255, 0], [255, 255, 0], [92, 92, 255], [255, 0, 255], [0, 255, 255], [255, 255, 255],
];

function nearest16([r, g, b]: [number, number, number]): number {
  let best = 0;
  let bestDistance = Infinity;
  ANSI16.forEach(([R, G, B], i) => {
    const d = (r - R) ** 2 + (g - G) ** 2 + (b - B) ** 2;
    if (d < bestDistance) [best, bestDistance] = [i, d];
  });
  return best;
}

function to256([r, g, b]: [number, number, number]): number {
  const q = (v: number) => (v < 48 ? 0 : v < 115 ? 1 : Math.round((v - 35) / 40));
  const cube = 16 + 36 * q(r) + 6 * q(g) + q(b);
  const level = (i: number) => (i === 0 ? 0 : 55 + 40 * i);
  const cubeError = (r - level(q(r))) ** 2 + (g - level(q(g))) ** 2 + (b - level(q(b))) ** 2;
  const gray = Math.min(23, Math.max(0, Math.round(((r + g + b) / 3 - 8) / 10)));
  const v = 8 + gray * 10;
  const grayError = (r - v) ** 2 + (g - v) ** 2 + (b - v) ** 2;
  return grayError < cubeError ? 232 + gray : cube;
}

function sgr(hex: string | undefined, layer: "fg" | "bg", level: ColorLevel): string {
  if (!hex) return layer === "fg" ? "39" : "49";
  const color = rgb(hex);
  if (level === "truecolor") return `${layer === "fg" ? 38 : 48};2;${color.join(";")}`;
  if (level === "256") return `${layer === "fg" ? 38 : 48};5;${to256(color)}`;
  const i = nearest16(color);
  return String((layer === "fg" ? 30 : 40) + (i % 8) + (i >= 8 ? 60 : 0));
}

export function createRenderer(art: Art) {
  const sizeNames = Object.keys(art.sizes);

  function rows(size?: string): number[][] {
    const name = size ?? sizeNames[0];
    const source = art.sizes[name];
    if (!source) throw new Error(`Unknown size "${name}". Available: ${sizeNames.join(", ")}`);
    return source.map((row) => [...row].map((c) => (c === "." ? -1 : c.charCodeAt(0) - 97)));
  }

  function markSize(size?: string) {
    const r = rows(size);
    return { width: r[0]?.length ?? 0, height: Math.ceil(r.length / 2) };
  }

  function renderMark(options: MarkOptions = {}): string[] {
    const level = options.color ?? detectColorLevel();
    const hex = (i: number) => (art.palette[i].adaptive ? options.ink : art.palette[i].hex);
    const fixed = (i: number) => !art.palette[i].adaptive || options.ink !== undefined;
    const cell = (top: number, bottom: number): string => {
      if (top < 0 && bottom < 0) return " ";
      if (level === "none") return top < 0 ? "▄" : bottom < 0 ? "▀" : "█";
      if (top === bottom) return `${ESC}${sgr(hex(top), "fg", level)}m█${RESET}`;
      if (top < 0) return `${ESC}${sgr(hex(bottom), "fg", level)}m▄${RESET}`;
      if (bottom < 0) return `${ESC}${sgr(hex(top), "fg", level)}m▀${RESET}`;
      // Two colours in one cell. The terminal foreground can't be used as a
      // background, so an adaptive pixel always takes the foreground.
      const [glyph, fg, bg] = fixed(bottom) ? ["▀", top, bottom] : ["▄", bottom, top];
      return `${ESC}${sgr(hex(fg), "fg", level)};${sgr(hex(bg), "bg", level)}m${glyph}${RESET}`;
    };
    const grid = rows(options.size);
    const lines: string[] = [];
    for (let y = 0; y < grid.length; y += 2) {
      const top = grid[y];
      const bottom = grid[y + 1] ?? top.map(() => -1);
      lines.push(top.map((p, x) => cell(p, bottom[x])).join(""));
    }
    return lines;
  }

  function renderBanner(info: BannerInfo = {}, options: MarkOptions & { columns?: number } = {}): string {
    const level = options.color ?? detectColorLevel();
    const styled = (code: string, text: string) => (level === "none" ? text : `${ESC}${code}m${text}${RESET}`);
    const plain = [`${art.name}${info.version ? ` v${info.version}` : ""}`, ...(info.details ?? [])];
    const text = [
      styled("1", art.name) + (info.version ? " " + styled("2", `v${info.version}`) : ""),
      ...(info.details ?? []).map((line) => styled("2", line)),
    ];
    const mark = renderMark({ ...options, color: level });
    const columns = options.columns ?? process.stdout.columns ?? 80;
    const widest = Math.max(...plain.map((line) => line.length));
    if (columns < markSize(options.size).width + 3 + Math.min(widest, 20)) return text.join("\n");
    const start = Math.max(0, Math.floor((mark.length - text.length) / 2));
    return mark
      .map((line, i) => (text[i - start] === undefined ? line.trimEnd() : `${line}   ${text[i - start]}`))
      .concat(text.slice(mark.length - start))
      .join("\n");
  }

  /** Prints only on interactive terminals, so piped and --json output stay clean. */
  function printBanner(info: BannerInfo = {}, options: MarkOptions = {}, stream: NodeJS.WriteStream = process.stdout): void {
    if (!stream.isTTY) return;
    stream.write(`\n${renderBanner(info, { ...options, columns: stream.columns })}\n\n`);
  }

  return { sizes: sizeNames, markSize, renderMark, renderBanner, printBanner };
}

